// Recursive Cooley-Tukey FFT. Complex numbers are { re, im }.
function fft(input) {
  const n = input.length;
  if (n === 1) return [input[0]];
  const even = fft(input.filter((_, i) => i % 2 === 0));
  const odd = fft(input.filter((_, i) => i % 2 === 1));
  const result = new Array(n);
  for (let k = 0; k < n / 2; k++) {
    const angle = (-2 * Math.PI * k) / n;
    const tw = { re: Math.cos(angle), im: Math.sin(angle)};
    const t = { re: tw.re * odd[k].re - tw.im * odd[k].im, im: tw.re * odd[k].im + tw.im * odd[k].re,};
    result[k] = { re: even[k].re + t.re, im: even[k].im + t.im};
    result[k + n / 2] = { re: even[k].re - t.re, im: even[k].im - t.im};
  }
  return result;
}

const signal = [1, 1, 1, 1].map(x => ({ re: x, im: 0 }));
const spectrum = fft(signal);
console.log(spectrum.map(c => Math.round(c.re) + '+' + Math.round(c.im) + 'i').join(', '));

