public class FFT {
    static class Complex { double re, im; Complex(double r,double i){re=r;im=i;}
        Complex add(Complex o){return new Complex(re+o.re,im+o.im);}
        Complex sub(Complex o){return new Complex(re-o.re,im-o.im);}
        Complex mul(Complex o){return new Complex(re*o.re-im*o.im,re*o.im+im*o.re);}
    }
    static void fft(Complex[] a, boolean inv) {
        int n=a.length;
        for(int i=1,j=0;i<n;i++){
            int bit=n>>1;
            for(;(j&bit)!=0;bit>>=1) j^=bit;
            j^=bit; if(i<j){Complex t=a[i];a[i]=a[j];a[j]=t;}
        }
        for(int len=2;len<=n;len*=2){
            double ang=2*Math.PI/len*(inv?-1:1);
            Complex wlen=new Complex(Math.cos(ang),Math.sin(ang));
            for(int i=0;i<n;i+=len){
                Complex w=new Complex(1,0);
                for(int j=0;j<len/2;j++,w=w.mul(wlen)){
                    Complex u=a[i+j],v=a[i+j+len/2].mul(w);
                    a[i+j]=u.add(v);a[i+j+len/2]=u.sub(v);
                }
            }
        }
        if(inv) for(Complex x:a){x.re/=n;x.im/=n;}
    }
}

